"""Rust emitter: IR programs -> `impl<const W: usize> Basis<W>` + GenContext.

The emitted code is W-generic and does not allocate per term.
Nodes that depend only on the generator g are computed once in
`make_signed_gen_context` and stored in the context (partial evaluation).
Only `branch_table` allocates, and it runs once per gate.
"""

from __future__ import annotations

import math

from .analysis import split_program
from .ir import BITS, BasisIR

HEADER = """\
// Generated by propaq.tracer ({name}, IR hash {hash}). Do not edit.
#![allow(clippy::all, unused, non_snake_case, non_camel_case_types)]

use num_complex::Complex64;
use propaq_core::basis::{{Basis, BasisKind}};
use propaq_core::fold::LinearFold;
use propaq_core::strings::BasisString;
"""

PRELUDE = r"""
// ---- word helpers (all W-generic, no allocation) ----
#[cfg(all(target_arch = "x86_64", target_feature = "bmi2"))]
#[inline(always)]
fn pext64(x: u64, m: u64) -> u64 {
    unsafe { core::arch::x86_64::_pext_u64(x, m) }
}
#[cfg(not(all(target_arch = "x86_64", target_feature = "bmi2")))]
#[inline(always)]
fn pext64(x: u64, mut m: u64) -> u64 {
    let (mut out, mut k) = (0u64, 0u32);
    while m != 0 {
        let low = m & m.wrapping_neg();
        if x & low != 0 {
            out |= 1u64 << k;
        }
        k += 1;
        m ^= low;
    }
    out
}
#[cfg(all(target_arch = "x86_64", target_feature = "bmi2"))]
#[inline(always)]
fn pdep64(x: u64, m: u64) -> u64 {
    unsafe { core::arch::x86_64::_pdep_u64(x, m) }
}
#[cfg(not(all(target_arch = "x86_64", target_feature = "bmi2")))]
#[inline(always)]
fn pdep64(x: u64, mut m: u64) -> u64 {
    let (mut out, mut k) = (0u64, 0u32);
    while m != 0 {
        let low = m & m.wrapping_neg();
        if (x >> k) & 1 != 0 {
            out |= low;
        }
        k += 1;
        m ^= low;
    }
    out
}
#[inline(always)]
fn popcount<const W: usize>(a: &[u64; W]) -> i64 {
    let mut n = 0u32;
    for i in 0..W {
        n += a[i].count_ones();
    }
    n as i64
}
#[inline(always)]
fn band<const W: usize>(a: &[u64; W], b: &[u64; W]) -> [u64; W] {
    let mut r = [0u64; W];
    for i in 0..W {
        r[i] = a[i] & b[i];
    }
    r
}
#[inline(always)]
fn bor<const W: usize>(a: &[u64; W], b: &[u64; W]) -> [u64; W] {
    let mut r = [0u64; W];
    for i in 0..W {
        r[i] = a[i] | b[i];
    }
    r
}
#[inline(always)]
fn bxor<const W: usize>(a: &[u64; W], b: &[u64; W]) -> [u64; W] {
    let mut r = [0u64; W];
    for i in 0..W {
        r[i] = a[i] ^ b[i];
    }
    r
}
#[inline(always)]
fn bnot<const W: usize>(a: &[u64; W]) -> [u64; W] {
    let mut r = [0u64; W];
    for i in 0..W {
        r[i] = !a[i];
    }
    r
}
#[inline(always)]
fn shl_w<const W: usize>(a: &[u64; W], c: u32) -> [u64; W] {
    let mut r = [0u64; W];
    for i in 0..W {
        r[i] = a[i] << c;
    }
    r
}
#[inline(always)]
fn shr_w<const W: usize>(a: &[u64; W], c: u32) -> [u64; W] {
    let mut r = [0u64; W];
    for i in 0..W {
        r[i] = a[i] >> c;
    }
    r
}
#[inline(always)]
fn pext_w<const W: usize>(a: &[u64; W], m: u64) -> [u64; W] {
    let mut r = [0u64; W];
    for i in 0..W {
        r[i] = pext64(a[i], m);
    }
    r
}
#[inline(always)]
fn pdep_w<const W: usize>(a: &[u64; W], m: u64) -> [u64; W] {
    let mut r = [0u64; W];
    for i in 0..W {
        r[i] = pdep64(a[i], m);
    }
    r
}
/// Exclusive prefix XOR over all bits, across words.
#[inline(always)]
fn prefix_parity<const W: usize>(a: &[u64; W]) -> [u64; W] {
    let mut r = [0u64; W];
    let mut carry = 0u64;
    for i in 0..W {
        let mut p = a[i];
        p ^= p << 1;
        p ^= p << 2;
        p ^= p << 4;
        p ^= p << 8;
        p ^= p << 16;
        p ^= p << 32;
        r[i] = (p ^ a[i]) ^ carry;
        carry ^= 0u64.wrapping_sub((p >> 63) & 1);
    }
    r
}
#[inline(always)]
fn select_bits<const W: usize>(c: i64, a: &[u64; W], b: &[u64; W]) -> [u64; W] {
    if c != 0 {
        *a
    } else {
        *b
    }
}
/// Bits below `n_bits` set.
#[inline(always)]
fn active_bits<const W: usize>(n_bits: usize) -> [u64; W] {
    let mut r = [0u64; W];
    for i in 0..W {
        let low = i * 64;
        r[i] = if low >= n_bits {
            0
        } else if n_bits - low >= 64 {
            u64::MAX
        } else {
            (1u64 << (n_bits - low)) - 1
        };
    }
    r
}
/// Unit-bit u of `a` goes to bit `u * b + off`.
#[inline(always)]
fn expand_units<const W: usize>(a: &[u64; W], b: usize, off: usize) -> [u64; W] {
    let per = 64 / b;
    let low = if per == 64 { u64::MAX } else { (1u64 << per) - 1 };
    let mut dep = 0u64;
    for i in 0..per {
        dep |= 1u64 << (i * b + off);
    }
    let mut r = [0u64; W];
    for j in 0..W {
        let start = j * per;
        r[j] = pdep64((a[start / 64] >> (start % 64)) & low, dep);
    }
    r
}
"""

WEYL_TABLE = r"""
/// Branch table `[chi][k]` (row-major, M rows, M columns) of
/// U = exp(-i theta H / 2), H = (W_g + W_g^dag) / 2, for a Weyl-type basis.
/// For Hermitian W_g this is the native exp(-i theta G / 2).
/// `q` is the self phase of g: W_g^k = w^(q k (k-1) / 2) W_(k g), w = exp(2 pi i / M).
/// W_g^M = w^(q M (M-1) / 2) = c I. Eigenvalues are mu w^j with mu^M = c.
fn weyl_table(q: i64, theta: f64, m: usize) -> Vec<Complex64> {
    let w = |p: f64| Complex64::from_polar(1.0, 2.0 * std::f64::consts::PI * p / m as f64);
    let mu = Complex64::from_polar(1.0, std::f64::consts::PI * q as f64 * (m as f64 - 1.0) / m as f64);
    let lam: Vec<Complex64> = (0..m).map(|j| mu * w(j as f64)).collect();
    let mut tab = vec![Complex64::new(0.0, 0.0); m * m];
    for chi in 0..m {
        let chic = w(chi as f64);
        let f: Vec<Complex64> = lam
            .iter()
            .map(|l| (Complex64::new(0.0, 0.25 * theta) * ((chic - 1.0) * l + (chic.conj() - 1.0) * l.conj())).exp())
            .collect();
        for k in 0..m {
            let mut ck = Complex64::new(0.0, 0.0);
            for j in 0..m {
                ck += f[j] * lam[j].conj().powi(k as i32);
            }
            let self_phase = w((q * (k * k.saturating_sub(1) / 2) as i64) as f64);
            tab[chi * m + k] = ck / m as f64 * self_phase;
        }
    }
    tab
}
"""


def camel(name):
    return "".join(p.capitalize() for p in name.split("_"))


def _flt(x):
    if abs(x) < 1e-15:
        return "0.0"
    if abs(x - round(x)) < 1e-15:
        return f"{float(round(x))!r}"
    return repr(x)


def _int_lit(v):
    return f"({v}i64)" if v < 0 else f"{v}i64"


def _word_lit(v):
    return f"0x{v:016x}u64"


class _Emitter:
    def __init__(self, ir: BasisIR, type_name=None):
        self.ir = ir
        self.meta = ir.meta
        self.b = ir.meta["bits_per_unit"]
        self.type_name = type_name or camel(ir.meta["name"])
        self.ctx_name = f"{self.type_name}GenContext"
        self.fields = {}  # structural key -> field name
        self.field_kind = {}
        self.gen_vars = {}  # structural key -> variable in make_signed_gen_context
        self.gen_code = []
        self.splits = {}

    # ---- node expressions ----
    def lit(self, prog, i):
        n = prog.nodes[i]
        if n.op == "const":
            return _int_lit(n.imm)
        return f"[{_word_lit(n.imm)}; W]"

    def expr(self, n, a):
        op, imm = n.op, n.imm
        if n.kind == BITS:
            two = {"and": "band", "or": "bor", "xor": "bxor"}
            if op in two:
                return f"{two[op]}(&{a[0]}, &{a[1]})"
            if op == "not":
                return f"bnot(&{a[0]})"
            if op in ("shl_w", "shr_w"):
                return f"{op}(&{a[0]}, {imm})"
            if op in ("pext_w", "pdep_w"):
                return f"{op}(&{a[0]}, {_word_lit(imm)})"
            if op == "prefix_parity":
                return f"prefix_parity(&{a[0]})"
            if op == "expand_units":
                return f"expand_units(&{a[0]}, {imm[0]}, {imm[1]})"
            if op == "select_bits":
                return f"select_bits({a[0]}, &{a[1]}, &{a[2]})"
            if op == "active":
                return f"active_bits::<W>(n_units * {self.b})"
        else:
            bin_ = {"add": "wrapping_add", "sub": "wrapping_sub", "mul": "wrapping_mul"}
            if op in bin_:
                return f"{a[0]}.{bin_[op]}({a[1]})"
            if op in ("and", "or", "xor"):
                sym = {"and": "&", "or": "|", "xor": "^"}[op]
                return f"({a[0]} {sym} {a[1]})"
            if op == "popcount":
                return f"popcount(&{a[0]})"
            if op == "shl":
                return f"{a[0]}.wrapping_shl({imm})"
            if op == "shr":
                return f"({a[0]} >> {imm})"
            if op == "rem":
                return f"{a[0]}.rem_euclid({imm}i64)"
            if op in ("eq", "ne", "lt"):
                sym = {"eq": "==", "ne": "!=", "lt": "<"}[op]
                return f"(({a[0]} {sym} {a[1]}) as i64)"
            if op == "select":
                return f"(if {a[0]} != 0 {{ {a[1]} }} else {{ {a[2]} }})"
            if op == "n_units":
                return "(n_units as i64)"
        raise NotImplementedError(op)

    def ty(self, kind):
        return "[u64; W]" if kind == BITS else "i64"

    # ---- partial evaluation bookkeeping ----
    def field_for(self, key, kind):
        if key not in self.fields:
            self.fields[key] = f"h{len(self.fields)}"
            self.field_kind[key] = kind
        return self.fields[key]

    def plan_gen(self, name):
        """Emit generator-side code for program `name`; return its Split."""
        prog = self.ir.programs[name]
        sp = split_program(prog, gen_inputs=(0,))
        self.splits[name] = sp
        for i in sp.gen_needed:
            key = sp.keys[i]
            n = prog.nodes[i]
            if key in self.gen_vars or n.op == "input":
                continue
            args = []
            for a in n.args:
                if prog.nodes[a].op in ("const", "const_word"):
                    args.append(self.lit(prog, a))
                elif prog.nodes[a].op == "input":
                    args.append("g")
                else:
                    args.append(self.gen_vars[sp.keys[a]])
            var = f"k{len(self.gen_vars)}"
            self.gen_vars[key] = var
            self.gen_code.append(f"let {var}: {self.ty(n.kind)} = {self.expr(n, args)};")
        for i in sp.frontier:
            self.field_for(sp.keys[i], prog.nodes[i].kind)
        return sp

    def late_body(self, name, input_exprs, indent="        "):
        """Per-term code. Returns (lines, function giving each output expression)."""
        prog = self.ir.programs[name]
        sp = self.splits.get(name) or split_program(prog, gen_inputs=())
        names = {}
        lines = []

        def ref(a):
            n = prog.nodes[a]
            if n.op in ("const", "const_word"):
                return self.lit(prog, a)
            if sp.cls[a] == "gen":
                if n.op == "input":
                    return "g"
                return f"ctx.{self.fields[sp.keys[a]]}"
            return names[a]

        for i in sp.late_needed:
            n = prog.nodes[i]
            if n.op in ("const", "const_word"):
                continue
            var = f"v{i}"
            names[i] = var
            if n.op == "input":
                lines.append(f"let {var}: {self.ty(n.kind)} = {input_exprs[n.imm]};")
            else:
                lines.append(f"let {var}: {self.ty(n.kind)} = {self.expr(n, [ref(a) for a in n.args])};")
        outs = [ref(o) for o in prog.outputs]
        return lines, outs

    # ---- emission ----
    def emit(self):
        ir, m = self.ir, self.meta
        D, M, BR = m["phase_order"], m["char_modulus"], m["branches"]
        has_fold = "fold" in ir.programs
        g_progs = ["character", "product"] + [f"branch_{k}" for k in range(1, BR) if BR > 2]
        if BR > 2:
            g_progs.append("self_phase")
        for name in g_progs:
            self.plan_gen(name)
        # Fold program: all nodes are generator-only. Emit them straight.
        fold_lines, fold_outs = [], []
        if has_fold:
            fp = ir.programs["fold"]
            fnames = {}
            for i, n in enumerate(fp.nodes):
                if n.op in ("const", "const_word"):
                    continue
                if n.op == "input":
                    fnames[i] = "g"
                    continue
                args = [self.lit(fp, a) if fp.nodes[a].op in ("const", "const_word") else fnames[a] for a in n.args]
                fnames[i] = f"f{i}"
                fold_lines.append(f"let f{i}: {self.ty(n.kind)} = {self.expr(n, args)};")
            fold_outs = [self.lit(fp, o) if fp.nodes[o].op in ("const", "const_word") else fnames[o] for o in fp.outputs]

        T, C = self.type_name, self.ctx_name
        out = [HEADER.format(name=m["name"], hash=ir.hash16()), PRELUDE]
        if BR > 2:
            out.append(WEYL_TABLE)
        phases = ", ".join(
            f"Complex64::new({_flt(math.cos(2 * math.pi * e / D))}, {_flt(math.sin(2 * math.pi * e / D))})" for e in range(D)
        )
        trace_re = ", ".join(_flt(math.cos(2 * math.pi * e / D)) for e in range(D))
        out.append(f"const PHASES: [Complex64; {D}] = [{phases}];")
        out.append(f"const TRACE_RE: [f64; {D}] = [{trace_re}];\n")
        out.append(f"/// The `{m['name']}` basis, generated by the tracer.\npub struct {T};\n")
        # Context struct.
        out.append(f"/// Per-gate data: the generator, its sign, the fold and hoisted generator-only nodes.")
        out.append(f"pub struct {C}<const W: usize> {{\n    gen: BasisString<W>,\n    sign: f64,")
        if has_fold:
            out.append("    fold: LinearFold<W>,")
        for key, f in self.fields.items():
            out.append(f"    {f}: {self.ty(self.field_kind[key])},")
        out.append("}\n")
        # Impl.
        out.append(f"impl<const W: usize> Basis<W> for {T} {{")
        out.append("    const KIND: BasisKind = BasisKind::Custom;")
        out.append(f"    const BRANCHES: usize = {BR};\n    const CHAR_MODULUS: u32 = {M};\n    const PHASE_ORDER: u32 = {D};")
        out.append(f"    type GenContext = {C}<W>;\n")
        out.append("    #[inline]\n    fn make_signed_gen_context(gen: &BasisString<W>, sign: f64) -> Self::GenContext {")
        out.append("        let g: [u64; W] = *gen.words();")
        for ln in self.gen_code:
            out.append("        " + ln)
        for ln in fold_lines:
            out.append("        " + ln)
        out.append(f"        {C} {{\n            gen: *gen,\n            sign,")
        if has_fold:
            out.append(
                f"            fold: LinearFold {{ modulus: {M}, masks: [BasisString::from_words({fold_outs[0]}), "
                f"BasisString::from_words({fold_outs[1]}), BasisString::from_words({fold_outs[2]})], use_parity: {fold_outs[3]} != 0 }},"
            )
        for key, f in self.fields.items():
            out.append(f"            {f}: {self.gen_vars[key]},")
        out.append("        }\n    }\n")
        out.append("    #[inline]\n    fn generator(ctx: &Self::GenContext) -> &BasisString<W> {\n        &ctx.gen\n    }\n")
        out.append(
            "    #[inline]\n    fn anticommutes(ctx: &Self::GenContext, mono: &BasisString<W>) -> bool {\n"
            "        <Self as Basis<W>>::character(ctx, mono) != 0\n    }\n"
        )
        out.append("    #[inline]\n    fn fold_generator(ctx: &Self::GenContext) -> &BasisString<W> {")
        out.append("        &ctx.fold.masks[0]\n    }\n" if has_fold else "        &ctx.gen\n    }\n")
        if has_fold:
            out.append("    #[inline]\n    fn fold_needs_odd_correction(ctx: &Self::GenContext) -> bool {\n        ctx.fold.use_parity\n    }\n")
        # character
        lines, outs = self.late_body("character", [None, "*mono.words()"])
        out.append("    #[inline]\n    fn character(ctx: &Self::GenContext, mono: &BasisString<W>) -> u32 {")
        out.append("        let g: [u64; W] = *ctx.gen.words();")
        out += ["        " + ln for ln in lines]
        out.append(f"        {outs[0]}.rem_euclid({M}i64) as u32\n    }}\n")
        # linear_fold
        out.append("    #[inline]\n    fn linear_fold(ctx: &Self::GenContext) -> Option<LinearFold<W>> {")
        out.append("        Some(ctx.fold.clone())\n    }\n" if has_fold else "        None\n    }\n")
        # product
        lines, outs = self.late_body("product", [None, "*mono.words()"])
        out.append("    #[inline]\n    fn product(ctx: &Self::GenContext, mono: &BasisString<W>) -> (BasisString<W>, Complex64) {")
        out.append("        let g: [u64; W] = *ctx.gen.words();")
        out += ["        " + ln for ln in lines]
        out.append(f"        (BasisString::from_words({outs[0]}), PHASES[{outs[1]}.rem_euclid({D}i64) as usize] * ctx.sign)\n    }}\n")
        # branch and table
        if BR > 2:
            out.append("    #[inline]\n    fn branch(ctx: &Self::GenContext, mono: &BasisString<W>, k: usize) -> (BasisString<W>, Complex64) {")
            out.append("        let g: [u64; W] = *ctx.gen.words();\n        match k {")
            for k in range(1, BR):
                lines, outs = self.late_body(f"branch_{k}", [None, "*mono.words()"])
                out.append(f"            {k} => {{")
                out += ["                " + ln for ln in lines]
                out.append(f"                (BasisString::from_words({outs[0]}), PHASES[{outs[1]}.rem_euclid({D}i64) as usize])\n            }}")
            out.append('            _ => unreachable!("branch index out of range"),\n        }\n    }\n')
            sp = self.splits["self_phase"]
            sp_field = self.fields[sp.keys[sp.program.outputs[0]]]
            out.append("    fn branch_table(ctx: &Self::GenContext, theta: f64) -> Vec<Complex64> {")
            out.append(f"        weyl_table(ctx.{sp_field}, ctx.sign * theta, {M})\n    }}\n")
        # weight
        lines, outs = self.late_body("weight", ["*mono.words()"])
        out.append("    #[inline]\n    fn weight(mono: &BasisString<W>, n_units: usize) -> u32 {")
        out += ["        " + ln for ln in lines]
        out.append(f"        {outs[0]}.max(0) as u32\n    }}\n")
        # trace
        lines, outs = self.late_body("trace", ["*mono.words()", "diag"])
        out.append("    fn trace(mono: &BasisString<W>, n_units: usize, diag_state: &[u64]) -> f64 {")
        out.append("        let mut diag = [0u64; W];\n        for (d, s) in diag.iter_mut().zip(diag_state) {\n            *d = *s;\n        }")
        out += ["        " + ln for ln in lines]
        out.append(f"        if {outs[0]} == 0 {{\n            0.0\n        }} else {{\n            TRACE_RE[{outs[1]}.rem_euclid({D}i64) as usize]\n        }}\n    }}")
        out.append("}\n")
        return "\n".join(out)


def emit_rust(ir: BasisIR, type_name=None) -> str:
    """Emit the Rust source of one basis. `ir` should have its fold added."""
    m = ir.meta
    if m["branches"] > 2 and not (m["branches"] == m["char_modulus"] == m["phase_order"]):
        raise NotImplementedError("the Weyl branch table needs branches == char_modulus == phase_order")
    return _Emitter(ir, type_name).emit()


def hoisted_fields(ir: BasisIR):
    """The context fields: list of Hoisted(program, node) for tests.

    Every entry is a generator-only node (see `analysis.classify`).
    """
    from .analysis import Hoisted

    em = _Emitter(ir)
    m = ir.meta
    names = ["character", "product"]
    if m["branches"] > 2:
        names += [f"branch_{k}" for k in range(1, m["branches"])] + ["self_phase"]
    seen = {}
    for name in names:
        sp = em.plan_gen(name)
        for i in sp.frontier:
            key = sp.keys[i]
            if key not in seen:
                seen[key] = Hoisted(em.fields[key], key, name, i, sp.program.nodes[i].kind)
    return list(seen.values())
